int main(int argc, char *argv[])
{
  struct deskmate_client_s client;
  struct deskmate_mqtt_config_s config = { .port = "1883" };
  char nonce[DESKMATE_NONCE_MAX + 1];
  int option;

  while ((option = getopt(argc, argv, "h:p:u:w:d:")) != -1) {
    switch (option) {
      case 'h': config.host = optarg; break;
      case 'p': config.port = optarg; break;
      case 'u': config.username = optarg; break;
      case 'w': config.password = optarg; break;
      case 'd': config.device_id = optarg; break;
      default: usage(argv[0]); return 2;
    }
  }

  if (config.host == NULL || config.username == NULL ||
      config.password == NULL || config.device_id == NULL || make_nonce(nonce, sizeof(nonce)) < 0) {
    usage(argv[0]);
    return 2;
  }

  deskmate_client_init(&client, nonce);
  printf("DeskMate client started: %s\n", deskmate_state_name(client.state));
  return deskmate_mqtt_run(&config, &client) == 0 ? 0 : 1;
} 这样这么写int deskmate_mqtt_run(const struct deskmate_mqtt_config_s *config,
                      struct deskmate_client_s *client)
{
  struct deskmate_mqtt_s transport;
  char client_id[DESKMATE_MQTT_DEVICE_ID_MAX + 16];
  int fd;
  int written;

  if (config == NULL || client == NULL || config->host == NULL ||
      config->port == NULL || config->username == NULL ||
      config->password == NULL || config->device_id == NULL ||
      make_topics(config, &transport) < 0) {
    return -1;
  }

  written = snprintf(client_id, sizeof(client_id), "deskmate-device-%s",
                     config->device_id);
  if (written < 0 || (size_t)written >= sizeof(client_id)) {
    return -1;
  }

  for (;;) {
    printf("DeskMate MQTT: connecting to %s:%s\n", config->host, config->port);
    fd = connect_socket(config->host, config->port);
    if (fd < 0) {
      printf("DeskMate MQTT: broker connection failed\n");
      sleep(1);
      continue;
    }

    memset(&transport, 0, sizeof(transport));
    transport.client = client;
    if (make_topics(config, &transport) < 0) {
      close(fd);
      return -1;
    }

    g_transport = &transport;
    mqtt_init(&transport.mqtt, fd, transport.sendbuf, sizeof(transport.sendbuf),
              transport.recvbuf, sizeof(transport.recvbuf), publish_callback);
    if (mqtt_connect(&transport.mqtt, client_id, NULL, NULL, 0, config->username,
                     config->password, MQTT_CONNECT_CLEAN_SESSION, 30) != MQTT_OK ||
        mqtt_subscribe(&transport.mqtt, transport.to_device, 0) != MQTT_OK ||
        send_hello(&transport) < 0) {
      printf("DeskMate MQTT: connect or subscribe failed\n");
      close(fd);
      g_transport = NULL;
      sleep(1);
      continue;
    }

    printf("DeskMate MQTT connected as %s\n", config->device_id);
    while (mqtt_sync(&transport.mqtt) == MQTT_OK &&
           transport.mqtt.error == MQTT_OK) {
      deskmate_client_timeout(client, now_ms());
      usleep(100000U);
    }

    printf("DeskMate MQTT: disconnected\n");
    deskmate_client_link_down(client);
    close(fd);
    g_transport = NULL;
    sleep(1);
  }
